            "明细：上海凡川有需求共 【X】吨。向客户收取15%合同定金，加价5元每吨。自我司付款之日起至客户货款到我司账上为止，根据敞口部分(全额预付款扣除客户已支付定金的部分)按照0.55%月息(含税)按实际天数向客户收取超期费用;货到仓库后，货权在我司名下，客户分批带款提货;合同正常周期为签约日后180天，120天内按照0.55%月息(含税)标准计息，超过120天后按照0.65%月息(含税)标准计息，若超过180天不提货，我司保留没收定金并自行处理货物的权利。综上，此业务风险完全受控，合同履行有保障，并具有盈利空间，建议开展该钢材购销业务。",
